package org.springframework.samples.petclinic.rest.advice;

import java.time.LocalDate;

/**
 * Thrown when a request to create an owner would exceed the number of owners that may be registered
 * in a single day. Owners are grouped by their {@code registrationDate}; once a day already holds the
 * maximum number of owners any further create for that day is reported to the caller as an HTTP 429.
 */
public class OwnerDailyLimitExceededException extends RuntimeException {

    private final LocalDate date;

    private final int limit;

    public OwnerDailyLimitExceededException(LocalDate date, int limit) {
        super("Daily limit of " + limit + " owners already reached for: " + date);
        this.date = date;
        this.limit = limit;
    }

    public LocalDate getDate() {
        return this.date;
    }

    public int getLimit() {
        return this.limit;
    }
}

